745: static int proc_pid_permission(struct mnt_idmap *idmap,
746: 			       struct inode *inode, int mask)
747: {
748: 	struct proc_fs_info *fs_info = proc_sb_info(inode->i_sb);
749: 	struct task_struct *task;
750: 	bool has_perms;
751: 
752: 	task = get_proc_task(inode);
753: 	if (!task)
754: 		return -ESRCH;
755: 	has_perms = has_pid_permissions(fs_info, task, HIDEPID_NO_ACCESS);
756: 	put_task_struct(task);
757: 
758: 	if (!has_perms) {
759: 		if (fs_info->hide_pid == HIDEPID_INVISIBLE) {
760: 			/*
761: 			 * Let's make getdents(), stat(), and open()
762: 			 * consistent with each other.  If a process
763: 			 * may not stat() a file, it shouldn't be seen
764: 			 * in procfs at all.
765: 			 */
766: 			return -ENOENT;
767: 		}
768: 
769: 		return -EPERM;
770: 	}
771: 	return generic_permission(&nop_mnt_idmap, inode, mask);
772: }
