1105: static int __set_oom_adj(struct file *file, int oom_adj, bool legacy)
1106: {
1107: 	struct mm_struct *mm = NULL;
1108: 	struct task_struct *task;
1109: 	int err = 0;
1110: 
1111: 	task = get_proc_task(file_inode(file));
1112: 	if (!task)
1113: 		return -ESRCH;
1114: 
1115: 	mutex_lock(&oom_adj_mutex);
1116: 	if (legacy) {
1117: 		if (oom_adj < task->signal->oom_score_adj &&
1118: 				!capable(CAP_SYS_RESOURCE)) {
1119: 			err = -EACCES;
1120: 			goto err_unlock;
1121: 		}
1122: 		/*
1123: 		 * /proc/pid/oom_adj is provided for legacy purposes, ask users to use
1124: 		 * /proc/pid/oom_score_adj instead.
1125: 		 */
1126: 		pr_warn_once("%s (%d): /proc/%d/oom_adj is deprecated, please use /proc/%d/oom_score_adj instead.\n",
1127: 			  current->comm, task_pid_nr(current), task_pid_nr(task),
1128: 			  task_pid_nr(task));
1129: 	} else {
1130: 		if ((short)oom_adj < task->signal->oom_score_adj_min &&
1131: 				!capable(CAP_SYS_RESOURCE)) {
1132: 			err = -EACCES;
1133: 			goto err_unlock;
1134: 		}
1135: 	}
1136: 
1137: 	/*
1138: 	 * Make sure we will check other processes sharing the mm if this is
1139: 	 * not vfrok which wants its own oom_score_adj.
1140: 	 * pin the mm so it doesn't go away and get reused after task_unlock
1141: 	 */
1142: 	if (!task->vfork_done) {
1143: 		struct task_struct *p = find_lock_task_mm(task);
1144: 
1145: 		if (p) {
1146: 			if (mm_flags_test(MMF_MULTIPROCESS, p->mm)) {
1147: 				mm = p->mm;
1148: 				mmgrab(mm);
1149: 			}
1150: 			task_unlock(p);
1151: 		}
1152: 	}
1153: 
1154: 	task->signal->oom_score_adj = oom_adj;
1155: 	if (!legacy && has_capability_noaudit(current, CAP_SYS_RESOURCE))
1156: 		task->signal->oom_score_adj_min = (short)oom_adj;
1157: 	trace_oom_score_adj_update(task);
1158: 
1159: 	if (mm) {
1160: 		struct task_struct *p;
1161: 
1162: 		rcu_read_lock();
1163: 		for_each_process(p) {
1164: 			if (same_thread_group(task, p))
1165: 				continue;
1166: 
1167: 			/* do not touch kernel threads or the global init */
1168: 			if (p->flags & PF_KTHREAD || is_global_init(p))
1169: 				continue;
1170: 
1171: 			task_lock(p);
1172: 			if (!p->vfork_done && process_shares_mm(p, mm)) {
1173: 				p->signal->oom_score_adj = oom_adj;
1174: 				if (!legacy && has_capability_noaudit(current, CAP_SYS_RESOURCE))
1175: 					p->signal->oom_score_adj_min = (short)oom_adj;
1176: 			}
1177: 			task_unlock(p);
1178: 		}
1179: 		rcu_read_unlock();
1180: 		mmdrop(mm);
1181: 	}
1182: err_unlock:
1183: 	mutex_unlock(&oom_adj_mutex);
1184: 	put_task_struct(task);
1185: 	return err;
1186: }
