1188: /*
1189:  * /proc/pid/oom_adj exists solely for backwards compatibility with previous
1190:  * kernels.  The effective policy is defined by oom_score_adj, which has a
1191:  * different scale: oom_adj grew exponentially and oom_score_adj grows linearly.
1192:  * Values written to oom_adj are simply mapped linearly to oom_score_adj.
1193:  * Processes that become oom disabled via oom_adj will still be oom disabled
1194:  * with this implementation.
1195:  *
1196:  * oom_adj cannot be removed since existing userspace binaries use it.
1197:  */
1198: static ssize_t oom_adj_write(struct file *file, const char __user *buf,
1199: 			     size_t count, loff_t *ppos)
1200: {
1201: 	char buffer[PROC_NUMBUF] = {};
1202: 	int oom_adj;
1203: 	int err;
1204: 
1205: 	if (count > sizeof(buffer) - 1)
1206: 		count = sizeof(buffer) - 1;
1207: 	if (copy_from_user(buffer, buf, count)) {
1208: 		err = -EFAULT;
1209: 		goto out;
1210: 	}
1211: 
1212: 	err = kstrtoint(strstrip(buffer), 0, &oom_adj);
1213: 	if (err)
1214: 		goto out;
1215: 	if ((oom_adj < OOM_ADJUST_MIN || oom_adj > OOM_ADJUST_MAX) &&
1216: 	     oom_adj != OOM_DISABLE) {
1217: 		err = -EINVAL;
1218: 		goto out;
1219: 	}
1220: 
1221: 	/*
1222: 	 * Scale /proc/pid/oom_score_adj appropriately ensuring that a maximum
1223: 	 * value is always attainable.
1224: 	 */
1225: 	if (oom_adj == OOM_ADJUST_MAX)
1226: 		oom_adj = OOM_SCORE_ADJ_MAX;
1227: 	else
1228: 		oom_adj = (oom_adj * OOM_SCORE_ADJ_MAX) / -OOM_DISABLE;
1229: 
1230: 	err = __set_oom_adj(file, oom_adj, true);
1231: out:
1232: 	return err < 0 ? err : count;
1233: }
