1861: void task_dump_owner(struct task_struct *task, umode_t mode,
1862: 		     kuid_t *ruid, kgid_t *rgid)
1863: {
1864: 	/* Depending on the state of dumpable compute who should own a
1865: 	 * proc file for a task.
1866: 	 */
1867: 	const struct cred *cred;
1868: 	kuid_t uid;
1869: 	kgid_t gid;
1870: 
1871: 	if (unlikely(task->flags & PF_KTHREAD)) {
1872: 		*ruid = GLOBAL_ROOT_UID;
1873: 		*rgid = GLOBAL_ROOT_GID;
1874: 		return;
1875: 	}
1876: 
1877: 	/* Default to the tasks effective ownership */
1878: 	rcu_read_lock();
1879: 	cred = __task_cred(task);
1880: 	uid = cred->euid;
1881: 	gid = cred->egid;
1882: 	rcu_read_unlock();
1883: 
1884: 	/*
1885: 	 * Before the /proc/pid/status file was created the only way to read
1886: 	 * the effective uid of a /process was to stat /proc/pid.  Reading
1887: 	 * /proc/pid/status is slow enough that procps and other packages
1888: 	 * kept stating /proc/pid.  To keep the rules in /proc simple I have
1889: 	 * made this apply to all per process world readable and executable
1890: 	 * directories.
1891: 	 */
1892: 	if (mode != (S_IFDIR|S_IRUGO|S_IXUGO)) {
1893: 		struct mm_struct *mm;
1894: 		task_lock(task);
1895: 		mm = task->mm;
1896: 		/* Make non-dumpable tasks owned by some root */
1897: 		if (mm) {
1898: 			if (get_dumpable(mm) != SUID_DUMP_USER) {
1899: 				struct user_namespace *user_ns = mm->user_ns;
1900: 
1901: 				uid = make_kuid(user_ns, 0);
1902: 				if (!uid_valid(uid))
1903: 					uid = GLOBAL_ROOT_UID;
1904: 
1905: 				gid = make_kgid(user_ns, 0);
1906: 				if (!gid_valid(gid))
1907: 					gid = GLOBAL_ROOT_GID;
1908: 			}
1909: 		} else {
1910: 			uid = GLOBAL_ROOT_UID;
1911: 			gid = GLOBAL_ROOT_GID;
1912: 		}
1913: 		task_unlock(task);
1914: 	}
1915: 	*ruid = uid;
1916: 	*rgid = gid;
1917: }
