1525: static struct mm_struct *dup_mm(struct task_struct *tsk,
1526: 				struct mm_struct *oldmm)
1527: {
1528: 	struct mm_struct *mm;
1529: 	int err;
1530: 
1531: 	mm = allocate_mm();
1532: 	if (!mm)
1533: 		goto fail_nomem;
1534: 
1535: 	memcpy(mm, oldmm, sizeof(*mm));
1536: 
1537: 	if (!mm_init(mm, tsk, mm->user_ns))
1538: 		goto fail_nomem;
1539: 
1540: 	uprobe_start_dup_mmap();
1541: 	err = dup_mmap(mm, oldmm);
1542: 	if (err)
1543: 		goto free_pt;
1544: 	uprobe_end_dup_mmap();
1545: 
1546: 	mm->hiwater_rss = get_mm_rss(mm);
1547: 	mm->hiwater_vm = mm->total_vm;
1548: 
1549: 	if (mm->binfmt && !try_module_get(mm->binfmt->module))
1550: 		goto free_pt;
1551: 
1552: 	return mm;
